shots.draw_js:
clearScene();setBig(null);
setEq("$$V^{\\pi}_k(s)\\;=\\;r(s,\\pi(s))+\\gamma\\sum_{s'}P(s'\\mid s,\\pi(s))\\,V^{\\pi}_{k-1}(s')$$","top");
backup({x:640,y:250,dy:84,r:18,spread:190,levels:["s","a","s"],branch:[1,3],hl:[0],
  labels:["当前状态","π(s)","后继"]});
setCap("自举 = 不再往下展开，直接<b>用上一轮的估计顶替剩余的一整棵子树</b>。");

clearScene();setEq(null);
setBig("DP 没有偏差","因为你自举的那个 V^π，本来就是 V^π");
setCap("这句话讲座里说了 —— 而它<b>不精确</b>。你自举的是 <b>V^π_{k−1}</b>，差别在下标上。");

clearScene();setBig(null);
setEq("$$\\lVert V^{\\pi}_k - V^{\\pi}\\rVert_\\infty \\;\\le\\; \\gamma^k\\,\\lVert V^{\\pi}_0 - V^{\\pi}\\rVert_\\infty$$","top");
lamps({y:300,gap:340,items:[
  {label:"采样误差",sub:"DP 没有",state:"on"},
  {label:"截断偏差",sub:"按 γ^k 消失",state:"dead"}]});
setCap("把「偏差」拆成两项：<b>采样误差</b>与<b>截断偏差</b>。DP 只有后者。");

clearScene();setBig(null);
setEq("$$\\gamma=0.9:\\quad \\gamma^k \\text{ 随 } k \\text{ 衰减}$$","top");
fillBars({vals:[0.900,0.810,0.729,0.656,0.590],order:[0,1,2,3,4],step:300,
  x:330,y:430,w:620,h:160,max:1,
  label:function(i){return "k="+(i+1);},
  cls:function(i){return "y";},
  fmt:function(v){return v.toFixed(3);}});
setCap("截断偏差<b>会消失</b>，而且是几何速率 —— 这是它和采样误差的根本区别。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"采样误差",sub:"DP 没有",state:"dead"},
  {label:"截断偏差",sub:"按 γ^k 消失",state:"on"},
  {label:"完全无偏",sub:"两者都不是",state:"dead"}]});
note("算力 vs 数据",640,420,"y");
setCap("<b>指名反驳</b>：DP 没有的是<b>采样误差</b>，不是偏差。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:300,items:[
  {label:"动态规划",sub:"算期望 · 自举",state:"on"},
  {label:"蒙特卡洛",sub:"抽样 · 不自举",state:"on"},
  {label:"时序差分",sub:"抽样 · 自举",state:"on"}]});
setCap("三个算法的差别，可以完全压进<b>两个是非问题</b>：期望算不算得出来、未来展不展开。");

clearScene();setEq(null);
setBig("TD 是 MC 和 DP 的折中","所以它的表现也介于两者之间");
setCap("前半句对。后半句把「各取一半」偷换成了「结果在中间」—— <b>混出来的可能是第三样东西</b>。");

clearScene();setBig(null);setEq(null);
note("算期望",533,204,"y");
note("抽样",658,204,"y");
gridworld({rows:2,cols:2,cs:125,y:218,x:470,
  cls:function(i,j){return (i===0&&j===0)?"b":((i===0&&j===1)?"v":((i===1&&j===1)?"g":""));},
  val:function(i,j){return [["DP","TD"],["穷举树","MC"]][i][j];}});
note("自举",448,278,"y","end");
note("不自举",448,403,"sm","end");
setCap("两根<b>独立</b>的轴，四个格子。<b>TD 在对角</b>，不在 DP 与 MC 的连线上。");

clearScene();setBig(null);
setEq("$$\\begin{aligned}\\text{DP}&:\\ V(s)\\leftarrow r+\\gamma\\textstyle\\sum_{s'}P(s'|s,a)\\,V(s')\\\\[2pt]\\text{MC}&:\\ V(s)\\leftarrow V(s)+\\alpha\\big[\\,G_t-V(s)\\,\\big]\\\\[2pt]\\text{TD}&:\\ V(s)\\leftarrow V(s)+\\alpha\\big[\\,r+\\gamma V(s')-V(s)\\,\\big]\\end{aligned}$$","top");
setCap("差别全在方括号里：<b>拿什么当「目标」</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:300,items:[
  {label:"机制上",sub:"确实各取一半",state:"on"},
  {label:"方差上",sub:"确实在中间",state:"on"},
  {label:"收敛目标上",sub:"不在中间",state:"dead"}]});
note("MC 还不要马尔可夫",640,420,"y");
setCap("<b>指名反驳</b>：机制各取一半，答案未必在中间。第九集给反例。");

clearScene();setBig(null);
setEq("$$G_t \\;=\\; r_t+\\gamma r_{t+1}+\\gamma^2 r_{t+2}+\\cdots+\\gamma^{T-t}r_T$$","top");
mdpChain({n:4,y:320,r:28,x:400,gap:160,
  label:function(i){return ["s₃","s₂","s₂","s₁"][i];},
  cls:function(i){return i===3?"g":"";},
  rew:function(i){return i===3?"+1":"0";},
  arcs:[[0,1,"","",0],[1,2,"","",0],[2,3,"","",0]]});
setCap("MC = <b>走完，然后平均</b>。没有模型，没有自举，没有 Bellman 方程。");

clearScene();setEq(null);
setBig("MC 只是个笨办法","能用 TD 的时候没理由用它");
setCap("「笨」是真的。但笨恰好意味着<b>假设更少</b> —— 少的那条是<b>马尔可夫性</b>。");

clearScene();setBig(null);
setEq("$$\\hat V^{\\pi}(s)\\;=\\;\\frac{1}{N(s)}\\sum_{i=1}^{N(s)} G^{(i)}(s)$$","top");
lamps({y:320,gap:340,items:[
  {label:"首次访问",sub:"只取第一次",state:"on"},
  {label:"于是 IID",sub:"无偏 + 相合",state:"on"}]});
setCap("<b>首次访问</b>：每回合每状态最多取一个样本，于是样本之间 <b>IID</b>。");

clearScene();setBig(null);
setEq("$$\\text{一个回合之后（首次访问 MC）}$$","top");
fillBars({vals:[1,1,1,0,0,0,0],order:[0,1,2,3,4,5,6],step:300,
  x:210,y:430,w:860,h:170,max:1.2,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i<3?"g":"";},
  fmt:function(v){return v.toFixed(2);}});
setCap("MC 在<b>回合结束时一次性</b>更新所有访问过的状态；没走到的一动不动。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:300,items:[
  {label:"要的",sub:"回合制 · 够多回合",state:"on"},
  {label:"不要的",sub:"模型 · 马尔可夫",state:"on"},
  {label:"代价",sub:"方差高 · 只能离线",state:"dead"}]});
setCap("<b>指名反驳</b>：假设越少越「笨」，也<b>越难被环境悄悄证伪</b>。");
